writeFile('credits.lua', [[
-- Compatibility reads plus explicit, acknowledged house round transactions.
-- Disk files are identities only. No local balance is ever imported or written.
local config=require('derby.config')
local ui=require('derby.ui')
local M={}
local client
local bindings={}
local function demo()
 return not config.read() and (_G.ARCADE_DEV_MODE or (arcadeos and arcadeos.freeplay()))
end
local function network()
 if not client then client=require('derby.client').new() end
 return client
end
local function cardAt(path)
 if not path then return ui.card() end
 if path=='freeplay' and demo() then return {account='exhibition',path=path} end
 if not fs.exists(path..'/house-card.json') then return nil end
 local f=fs.open(path..'/house-card.json','r'); local ok,c=pcall(textutils.unserializeJSON,f.readAll()); f.close()
 if ok and type(c)=='table' then return {account=c.account,path=path} end
end
local function account(path)
 local bound=bindings[path or 'default']
 if bound then return bound end
 local c=cardAt(path); return c and c.account
end
local function checked(r)
 if not r.ok then error('HOUSE: '..tostring(r.error)..'. Funds remain at the host; use house station R to retry an unacknowledged request.',0) end
 return r
end
function M.findCards()
 if demo() then return {{path='freeplay',side='freeplay',name='EXHIBITION',credits=999}} end
 local cards={}
 for _,name in ipairs(peripheral.getNames()) do
  if peripheral.getType(name)=='drive' then
   local path=disk.getMountPath(name); local c=path and cardAt(path)
   if c and c.account then
    local r=checked(network():read({op='lookup',account=c.account}))
    cards[#cards+1]={path=path,side=name,name=r.name,credits=r.balance,account=c.account}
   end
  end
 end
 return cards
end
function M.get(path)
 if demo() then return 999 end
 local id=account(path); if not id then return 0 end
 return checked(network():read({op='lookup',account=id})).balance
end
function M.getName(path)
 if demo() then return 'EXHIBITION' end
 local id=account(path); if not id then return nil end
 return checked(network():read({op='lookup',account=id})).name
end
function M.lock(path)
 local c=cardAt(path); assert(c and c.account,'Insert a house account card')
 bindings[path or 'default']=c.account; return true
end
function M.unlock(path) bindings[path or 'default']=nil end
function M.beginRound(game,stake,maximum,path)
 if demo() then return {demo=true,game=game,stake=stake,maximum=maximum,account='exhibition'} end
 local c=cardAt(path); if not c or not c.account then return nil,'Insert a house account card' end
 local cli=network(); local localState=cli:localState()
 local old=localState.rounds[c.account]
 if old then
  local status=cli:read({op='roundStatus',round=old.round,account=c.account})
  if not status.ok or status.status=='open' then return nil,'Interrupted round '..old.round..': cashier must review/refund it' end
 end
 local id='arcade:'..os.getComputerID()..':'..(localState.counter+1)
 local r=cli:mutate({op='reserve',account=c.account,game=game,stake=stake,maximum=maximum,round=id})
 if not r.ok then return nil,r.error end
 local round={account=c.account,round=id,game=game,stake=stake,maximum=maximum}
 localState=cli:localState(); localState.rounds[c.account]=round; cli:saveLocal(localState)
 bindings[path or 'default']=c.account
 return round
end
function M.increaseRound(round,stake,maximum)
 if round.demo then round.stake=round.stake+stake; round.maximum=maximum; return true end
 local r=network():mutate({op='increase',round=round.round,account=round.account,stake=stake,maximum=maximum})
 if not r.ok then return false,r.error end
 round.stake=round.stake+stake; round.maximum=maximum
 local s=network():localState(); s.rounds[round.account]=round; network():saveLocal(s)
 return true
end
function M.settleRound(round,amount)
 if round.demo then return 999 end
 local r=checked(network():mutate({op='settle',round=round.round,account=round.account,amount=amount}))
 local s=network():localState(); s.rounds[round.account]=nil; network():saveLocal(s)
 return r.balance
end
function M.refundRound(round)
 if round.demo then return true end
 checked(network():mutate({op='refund',round=round.round,account=round.account}))
 local s=network():localState(); s.rounds[round.account]=nil; network():saveLocal(s); return true
end
-- Unchecked edits must fail loudly if a forgotten consumer tries the old API.
function M.set() error('HOUSE: local balance editing is retired',0) end
function M.add() error('HOUSE: use settleRound with an acknowledged reservation',0) end
function M.remove() error('HOUSE: use beginRound with a maximum return',0) end
function M.setName() error('HOUSE: account names belong to the host',0) end
return M
]])

writeFile('dedicate.lua', [[
-- dedicate.lua
-- Simple installer for dedicated (kiosk) machines.
-- Writes .arcade_config + kiosk flag files, then reboots.

local function clear()
    term.setBackgroundColor(colors.black)
    term.setTextColor(colors.white)
    term.clear()
    term.setCursorPos(1, 1)
end

local function writeFile(path, content)
    local f = fs.open(path, "w")
    if not f then return false end
    f.write(content)
    f.close()
    return true
end

local function deleteFile(path)
    if fs.exists(path) then
        fs.delete(path)
    end
end

local function isKioskEnabled()
    return fs.exists(".kiosk_mode")
end

local function currentCmd()
    if not fs.exists(".arcade_config") then return nil end
    local f = fs.open(".arcade_config", "r")
    if not f then return nil end
    local cmd = (f.readAll() or "")
    f.close()
    cmd = cmd:gsub("%s+", "")
    if cmd == "" then return nil end
    return cmd
end

local function pause()
    while true do
        local e, p1 = os.pullEvent()
        if e == "key" or e == "mouse_click" or e == "monitor_touch" then
            return
        end
    end
end

clear()
print("DEDICATED INSTALLER")
print("===================")
print("")
print("This will configure this computer to run")
print("only one game (kiosk mode).")
print("")
print("Current: " .. tostring(currentCmd() or "<none>"))
print("Kiosk:   " .. (isKioskEnabled() and "ON" or "OFF"))
print("")
print("1) Dedicated: Can't Stop (spawn)")
print("2) Disable kiosk (return to normal)")
print("")
print("Press 1 or 2...")

while true do
    local e, key = os.pullEvent("key")
    local name = keys.getName(key)

    if name == "one" or name == "numPad1" then
        -- Dedicated Can't Stop
        clear()
        print("Installing: Can't Stop kiosk...")
        writeFile(".arcade_config", "cant_stop")
        writeFile(".kiosk_mode", "1")
        writeFile(".kiosk_game", "cant_stop")
        print("Done. Rebooting...")
        sleep(1)
        os.reboot()

    elseif name == "two" or name == "numPad2" then
        -- Disable kiosk mode
        clear()
        print("Disabling kiosk mode...")
        deleteFile(".kiosk_mode")
        deleteFile(".kiosk_game")
        print("Done.")
        print("Tip: run setup.lua or edit .arcade_config")
        print("to choose a different default program.")
        print("")
        print("Rebooting...")
        sleep(1)
        os.reboot()
    end
end
]])

writeFile('derby/app.lua', [[
local M={}
function M.display(client,t,demo,verify)
 local sim=require('derby.sim'); local render=require('derby.render').new(t)
 local camera=settings.get('derby.camera','follow')
 local snapshot={phase='CONNECTING',positions={0,0,0},order={}}
 local race=demo and sim.new(1977); local tick=0
 local nextStep=os.epoch('utc'); local started=nextStep; local frames=0
 local timer=os.startTimer(.05)
 while true do
  local e,a,b,c=os.pullEvent()
  if e=='timer' and a==timer then
   if demo then
    local now=os.epoch('utc')
    while now>=nextStep do
     tick=tick+1; nextStep=nextStep+100
     if tick>30 and #race.order<3 then sim.step(race) end
    end
    snapshot={phase=tick<=30 and 'LOCKED' or (#race.order==3 and 'RESULT' or 'RUNNING'),positions=sim.positions(race),order=race.order,tick=race.tick,seconds=tick<=30 and math.ceil((30-tick)/10) or 0}
    if verify and #race.order==3 then
     local f=assert(fs.open('/derby-exhibition.json','w'))
     f.write(textutils.serializeJSON({seed=race.seed,order=race.order,frames=frames,elapsed=(now-started)/1000,fps=frames/math.max(.001,(now-started)/1000)})); f.close(); verify=false
    end
    if tick>race.tick+180 then race=sim.new(race.seed+1); tick=0 end
   else
    local r=client:read({op='snapshot'})
    snapshot=r.ok and r or {phase='HOUSE OFFLINE',positions=snapshot.positions,order={},paused=true}
   end
   render:draw(snapshot,camera,demo); frames=frames+1; timer=os.startTimer(.05)
  elseif e=='key' then
   if a==keys.q or a==keys.backspace then return
   elseif a==keys.c then camera=camera=='follow' and 'overview' or camera=='overview' and 'finish' or 'follow'
   elseif a==keys.one then camera='follow' elseif a==keys.two then camera='overview' elseif a==keys.three then camera='finish' end
   settings.set('derby.camera',camera); settings.save('/derby-settings')
   render:draw(snapshot,camera,demo)
  elseif e=='term_resize' or e=='monitor_resize' then render:draw(snapshot,camera,demo) end
 end
end
local function run(args)
 local config=require('derby.config'); local ui=require('derby.ui')
 settings.load('/derby-settings')
 local command=args[1] or 'station'
 if command=='--demo' or command=='demo' or (command=='station' and not config.read() and arcadeos and arcadeos.freeplay()) then return M.display(nil,ui.target(),true,args[2]=='--verify') end
 if command=='setup' then return config.setup(args[2],args[3],args[4]) end
 local c=config.read()
 if not c then print('House is not configured. Exhibition: race --demo'); print('Configure: house setup station <wired-modem> <host-id>'); return end
 if command=='host' then assert(c.role=='host','Configure this computer as the host'); return require('derby.server').run(c) end
 local client=require('derby.client').new(c)
 if command=='display' then return M.display(client,ui.target(),false)
 elseif command=='cashier' then assert(c.role=='cashier','Configure this computer as cashier'); return require('derby.cashier').run(client,ui.target())
 elseif command=='station' then return require('derby.station').run(client,ui.target()) end
 error('Use: house host|display|station|cashier|setup or race --demo',0)
end
function M.run(args)
 local t=require('derby.ui').target()
 local restore=require('derby.palette').save(t)
 local old=term.current()
 local ok,err=xpcall(function() run(args) end,debug.traceback)
 term.redirect(old); restore()
 if not ok then error(err,0) end
end
return M
]])

writeFile('derby/cashier.lua', [[
local ui=require('derby.ui')
