function M.run(client,t)
 local amounts={5,10,20,64}; local index=1; local status=''; local review
 local card,balance
 local function refresh()
  card=ui.card(); balance=nil
  if card and card.account then local r=client:read({op='lookup',account=card.account}); balance=r.ok and r.balance or nil; if not r.ok then status=r.error end end
 end
 local function draw()
  if not ui.usable(t) then return end
  ui.clear(t,'DIAMOND CASHIER')
  ui.line(t,3,' 1 diamond = 1 credit',colors.yellow)
  ui.line(t,5,' '..(card and (card.account or 'New card - issue an account') or 'Insert a floppy disk'))
  ui.line(t,6,' Balance: '..tostring(balance or 'UNAVAILABLE'))
  if review then
   ui.line(t,8,' '..review.op:upper()..' '..review.amount..' DIAMONDS',colors.yellow)
   ui.button(t,10,'ENTER: CONFIRM',true,false)
   ui.line(t,14,' Backspace: cancel')
  else
   ui.line(t,8,' Amount: '..amounts[index]..'  [Left/Right]',colors.yellow)
   ui.button(t,9,'[D] DEPOSIT from intake chest',false,false)
   ui.button(t,12,'[W] WITHDRAW to output chest',false,false)
   ui.line(t,16,' [N] Issue new card | [R] Retry request')
  end
  ui.line(t,18,' [Q] Exit | Empty output after withdrawal')
  local _,h=t.getSize(); ui.line(t,h,' '..status,colors.yellow)
 end
 local function create()
  refresh()
  if not card or card.account then status='Insert a disk without a house account'; return end
  local original=card
  local r=client:mutate({op='create',name='Guest'})
  if r.ok then
   local current=ui.card()
   if current and current.diskID==original.diskID and current.path==original.path then
    local f=assert(fs.open(current.path..'/house-card.json','w')); f.write(textutils.serializeJSON({account=r.account})); f.close()
    status='New account issued at zero. Old files preserved.'
   else status='Card removed. New account is empty; issue again.' end
  else status=r.error end
  refresh()
 end
 local function choose(op)
  refresh()
  if card and card.account and balance then review={op=op,account=card.account,amount=amounts[index]} else status='Insert an issued card and connect to house' end
 end
 local function confirm()
  if not review then return end
  local current=ui.card()
  if not current or current.account~=review.account then status='Card changed. Transfer not sent.'; review=nil; return end
  local r=client:mutate(review)
  status=r.ok and ('Transferred '..tostring(r.moved or 0)..' diamonds') or r.error
  review=nil; refresh()
 end
 refresh(); draw(); local timer=os.startTimer(1)
 while true do
  local e,a,b,c=os.pullEvent()
  if e=='timer' and a==timer then refresh(); timer=os.startTimer(1)
  elseif e=='key' then
   if a==keys.q then return elseif a==keys.backspace then review=nil
   elseif a==keys.enter then confirm()
   elseif a==keys.r then local r=client:retry(); status=r.ok and 'Request acknowledged; check balance' or r.error; refresh()
   elseif not review then
    if a==keys.left then index=(index-2)%#amounts+1 elseif a==keys.right then index=index%#amounts+1
    elseif a==keys.n then create() elseif a==keys.d then choose('deposit') elseif a==keys.w then choose('withdraw') end
   end
  elseif e=='monitor_touch' or e=='mouse_click' then
   if review and c>=10 and c<=12 then confirm()
   elseif not review then
    if c==8 then index=index%#amounts+1 elseif c>=9 and c<=11 then choose('deposit') elseif c>=12 and c<=14 then choose('withdraw') end
   end
  end
  draw()
 end
end
return M
]])

writeFile('derby/client.lua', [[
local config=require('derby.config')
local store=require('derby.store')
local M={protocol='pine-derby-house-v1'}
function M.new(c)
 c=c or config.read(); config.network(c); assert(c.host,'Host ID missing')
 local db=store.open('/house-client/state',{counter=0,bindings={},rounds={}})
 local state=db:get(); local api={config=c}
 function api:localState() return store.copy(state) end
 function api:saveLocal(s) db:save(s); state=s end
 local function transport(q)
  local token=tostring(os.getComputerID())..':'..tostring(os.epoch('utc'))..':'..tostring(math.random(1,999999))
  rednet.send(c.host,{token=token,request=q},M.protocol)
  local timer=os.startTimer(2)
  while true do
   local e,a,b,p=os.pullEvent()
   if e=='timer' and a==timer then return {ok=false,error='House offline; request retained for retry',offline=true} end
   if e=='rednet_message' and a==c.host and p==M.protocol and type(b)=='table' and b.token==token and type(b.result)=='table' then os.cancelTimer(timer); return b.result end
  end
 end
 function api:read(q) return transport(q) end
 local function deliver(q)
  local r=transport(q)
  if not r.offline and not r.pending then state.pending=nil; state.last={request=q,result=r}; db:save(state) end
  if r.pending then return {ok=false,error='Cashier transfer pending reconciliation',pending=true} end
  return r
 end
 function api:retry()
  if not state.pending then return state.last and state.last.result or {ok=false,error='No pending request'} end
  return deliver(state.pending)
 end
 function api:mutate(q)
  if state.pending then return {ok=false,error='Unacknowledged request: press R to retry before another action',pending=true} end
  state.counter=state.counter+1; q.id=tostring(os.getComputerID())..':'..state.counter
  state.pending=store.copy(q); db:save(state)
  return deliver(q)
 end
 return api
end
return M
]])

writeFile('derby/config.lua', [[
local M={path='/house-config.json'}
function M.read()
 if not fs.exists(M.path) then return nil end
 local f=assert(fs.open(M.path,'r')); local c=textutils.unserializeJSON(f.readAll()); f.close(); return c
end
function M.write(c)
 local f=assert(fs.open(M.path,'w')); f.write(textutils.serializeJSON(c)); f.close()
end
function M.network(c)
 assert(c and c.modem,'Run house setup first')
 local modem=assert(peripheral.wrap(c.modem),'Configured modem missing')
 assert(modem.isWireless and not modem.isWireless(),'Use the house wired modem')
 rednet.open(c.modem)
end
function M.setup(role,modem,host)
 assert(role=='host' or role=='station' or role=='display' or role=='cashier','Role: host, station, display or cashier')
 assert(not M.read(),'Configuration exists; back up and remove /house-config.json to reconfigure')
 local function ask(label) write(label..': '); return read() end
 local c={role=role,modem=modem or ask('Wired modem name')}
 M.network(c)
 if role=='host' then
  c.bank=ask('Bank inventory peripheral'); c.intake=ask('Cashier intake inventory'); c.payout=ask('Cashier output inventory')
  assert(c.bank~=c.intake and c.bank~=c.payout and c.intake~=c.payout,'Inventories must be separate')
  for _,name in ipairs({c.bank,c.intake,c.payout}) do
   local p=assert(peripheral.wrap(name),'Inventory unavailable: '..name); assert(p.list and p.pushItems,'Not an inventory: '..name)
  end
  c.clients={}
  for _,r in ipairs({'station','display','cashier'}) do
   local ids=ask(r..' computer IDs (comma separated)')
   for id in ids:gmatch('%d+') do assert(not c.clients[id],'Duplicate client ID'); c.clients[id]=r end
  end
  c.enabled=false
 else c.host=assert(tonumber(host or ask('House host computer ID')),'Host ID required') end
 M.write(c); print('Saved '..M.path..'. Run house '..role)
end
return M
]])

writeFile('derby/house.lua', [[
local ledger=require('derby.ledger')
local sim=require('derby.sim')
local M={}
function M.new(odds)
 local s=ledger.new(); s.raceNumber=0; s.paused=false; s.odds=odds
 return s
end
function M.nextRace(s,seed)
 s.raceNumber=s.raceNumber+1
 s.race={id='race-'..s.raceNumber,phase='OPEN',elapsed=0,seed=seed,tickets={},payouts=s.odds.payouts,oddsVersion=s.odds.version}
end
function M.bet(s,q)
 s.ticketReceipts=s.ticketReceipts or {}
 local receipt=s.ticketReceipts[q.id]
 if receipt then
  if receipt.account==q.account and receipt.race==q.race and receipt.horse==q.horse and receipt.stake==q.stake then return {ok=true,ticket=receipt.ticket} end
  return {ok=false,error='Transaction reused with different ticket'}
 end
 local race=s.race
 if not race or race.id~=q.race or race.phase~='OPEN' or s.paused then return {ok=false,error='Betting is closed'} end
 local old=race.tickets[q.account]
 if old then
  if old.transaction==q.id and old.horse==q.horse and old.stake==q.stake then return {ok=true,ticket=old} end
  return {ok=false,error='One confirmed ticket per account per race'}
 end
 if q.horse~=1 and q.horse~=2 and q.horse~=3 then return {ok=false,error='Choose a horse'} end
 if q.stake~=5 and q.stake~=10 and q.stake~=20 then return {ok=false,error='Choose 5, 10 or 20 credits'} end
 local payout=race.payouts[q.horse][tostring(q.stake)]
 local round=race.id..':'..q.account
 local r=ledger.apply(s,{op='reserve',id=q.id,round=round,account=q.account,stake=q.stake,maximum=math.max(q.stake,payout),game='derby',owner='host'})
 if not r.ok then return r end
 local ticket={horse=q.horse,stake=q.stake,returns=payout,round=round,transaction=q.id}
 race.tickets[q.account]=ticket
 s.ticketReceipts[q.id]={account=q.account,race=q.race,horse=q.horse,stake=q.stake,ticket=ticket}
 return {ok=true,ticket=ticket,balance=r.balance}
end
local function settle(s,cancel)
 local race=s.race
 for account,t in pairs(race.tickets) do
  local r=ledger.apply(s,{op=cancel and 'refund' or 'settle',id=race.id..':result:'..account,round=t.round,account=account,
   amount=not cancel and race.sim.order[1]==t.horse and t.returns or 0,owner='host'})
  assert(r.ok,r.error)
  t.paid=r.paid
 end
 race.phase=cancel and 'CANCELLED' or 'RESULT'; race.elapsed=0
end
function M.cancel(s)
 if not s.race or (s.race.phase~='OPEN' and s.race.phase~='LOCKED') then return {ok=false,error='Only unstarted races can be cancelled'} end
 if next(s.pending) then return {ok=false,error='Reconcile cashier first'} end
 settle(s,true); return {ok=true}
end
function M.tick(s,seed)
 if s.paused or next(s.pending) then return end
 if not s.race then M.nextRace(s,seed); return end
 local r=s.race
 r.elapsed=r.elapsed+1 -- tenths, advanced by the host only
 if r.phase=='OPEN' and r.elapsed>=600 then r.phase='LOCKED'; r.elapsed=0; r.sim=sim.new(r.seed)
 elseif r.phase=='LOCKED' and r.elapsed>=50 then r.phase='RUNNING'; r.elapsed=0
 elseif r.phase=='RUNNING' then sim.step(r.sim); if #r.sim.order==3 then settle(s,false) end
 elseif (r.phase=='RESULT' or r.phase=='CANCELLED') and r.elapsed>=150 then M.nextRace(s,seed) end
end
function M.snapshot(s,account)
 local r=s.race
 if not r then return {ok=true,paused=s.paused} end
 local seconds=r.phase=='OPEN' and math.ceil((600-r.elapsed)/10) or r.phase=='LOCKED' and math.ceil((50-r.elapsed)/10) or 0
 return {ok=true,id=r.id,phase=r.phase,paused=s.paused or next(s.pending)~=nil,seconds=seconds,payouts=r.payouts,
  positions=r.sim and sim.positions(r.sim) or {0,0,0},tick=r.sim and r.sim.tick or 0,
  order=r.sim and r.sim.order or {},ticket=account and r.tickets[account] or nil,oddsVersion=r.oddsVersion}
end
return M
]])

writeFile('derby/inventory.lua', [[
-- The host alone moves items. There is no automatic retry after an uncertain transfer.
local M={}
function M.count(inv)
 local n=0
 for _,item in pairs(inv.list()) do if item.name=='minecraft:diamond' then n=n+item.count end end
 return n
end
function M.move(source,destinationName,amount)
 local moved=0
 local slots={}; for slot in pairs(source.list()) do slots[#slots+1]=slot end; table.sort(slots)
 for _,slot in ipairs(slots) do
  local item=source.getItemDetail(slot)
  if item and item.name=='minecraft:diamond' and moved<amount then
   local n=source.pushItems(destinationName,slot,math.min(item.count,amount-moved))
   assert(type(n)=='number' and n>=0 and n%1==0 and n<=amount-moved,'Invalid inventory transfer receipt')
   moved=moved+n
  end
 end
 return moved
end
return M
]])

writeFile('derby/ledger.lua', [[
-- All money is integer credits, backed one-for-one by diamonds in the bank.
local M={}
local function canonical(v)
 if type(v)~='table' then return type(v)..':'..tostring(v) end
 local keys={}; for k in pairs(v) do keys[#keys+1]=k end
 table.sort(keys,function(a,b) return tostring(a)<tostring(b) end)
 local out={}; for _,k in ipairs(keys) do out[#out+1]=canonical(k)..'='..canonical(v[k]) end
 return '{'..table.concat(out,';')..'}'
end
function M.new() return {version=1,bank=0,accounts={},rounds={},transactions={},nextAccount=0,pending={}} end
local function integer(n) return type(n)=='number' and n==n and n>=0 and n%1==0 and n<=1000000000 end
function M.liability(s)
 local n=0
 for _,a in pairs(s.accounts) do n=n+a.balance end
 for _,r in pairs(s.rounds) do if r.status=='open' then n=n+r.maximum end end
 for _,p in pairs(s.pending) do if p.kind=='withdraw' then n=n+p.amount end end
 return n
end
function M.available(s) return s.bank-M.liability(s) end
function M.apply(s,q)
 local function fail(message) return {ok=false,error=message} end
 if type(q)~='table' or type(q.op)~='string' then return fail('Invalid request') end
 if q.op=='lookup' then
  local a=s.accounts[q.account]
  if not a then return fail('Insert a new house account card') end
  return {ok=true,balance=a.balance,name=a.name,account=q.account}
 elseif q.op=='roundStatus' then
  local r=s.rounds[q.round]; if not r or r.account~=q.account then return fail('Unknown round') end
  return {ok=true,status=r.status,paid=r.paid}
 elseif q.op=='status' then return s.transactions[q.id] and s.transactions[q.id].result or fail('Unknown transaction') end
 if type(q.id)~='string' or #q.id>160 then return fail('Transaction ID required') end
 -- The transport serialises a stable request and rejects reuse with different content.
 local fingerprint=canonical(q)
 if s.transactions[q.id] then
  if s.transactions[q.id].fingerprint~=fingerprint then return fail('Transaction ID reused with different request') end
  return s.transactions[q.id].result
 end
 local result
 local a=q.account and s.accounts[q.account]
 if q.op=='create' then
  s.nextAccount=s.nextAccount+1
  local id='house-'..s.nextAccount
  s.accounts[id]={name=tostring(q.name or 'Guest'):sub(1,24),balance=0}
  result={ok=true,account=id,balance=0}
 elseif q.op=='fund' then
  if not integer(q.amount) or q.amount<M.liability(s) then return fail('Bank cannot cover outstanding balances and reservations') end
  s.bank=q.amount; result={ok=true,bank=s.bank}
 elseif not a then return fail('Unknown account')
 elseif next(s.pending) then return fail('Cashier transfer requires reconciliation')
 elseif q.op=='reserve' then
  if not integer(q.stake) or not integer(q.maximum) or q.maximum<q.stake then return fail('Invalid stake or maximum return') end
  if a.balance<q.stake then return fail('Not enough credits') end
  if M.available(s)+q.stake<q.maximum then return fail('House reserve cannot cover this round') end
  if s.rounds[q.round] then return fail('Round already exists') end
  if type(q.round)~='string' or type(q.game)~='string' then return fail('Round and game required') end
  a.balance=a.balance-q.stake
  s.rounds[q.round]={account=q.account,stake=q.stake,maximum=q.maximum,status='open',game=q.game,owner=q.owner}
  result={ok=true,round=q.round,balance=a.balance}
 elseif q.op=='increase' then
  local r=s.rounds[q.round]
  if not r or r.status~='open' or r.account~=q.account or r.owner~=q.owner then return fail('Round unavailable') end
  if not integer(q.stake) or not integer(q.maximum) or q.maximum<r.maximum or q.maximum<r.stake+q.stake then return fail('Invalid increase') end
  if a.balance<q.stake or M.available(s)+r.maximum+q.stake<q.maximum then return fail('Insufficient credits or house reserve') end
  a.balance=a.balance-q.stake; r.stake=r.stake+q.stake; r.maximum=q.maximum
  result={ok=true,balance=a.balance}
 elseif q.op=='settle' or q.op=='refund' then
  local r=s.rounds[q.round]
  if not r or r.account~=q.account or r.owner~=q.owner then return fail('Round unavailable') end
  local amount=q.op=='refund' and r.stake or q.amount
  if not integer(amount) or amount>r.maximum then return fail('Return exceeds reservation') end
  if r.status~='open' then return fail('Round already settled') end
  r.status=q.op=='refund' and 'refunded' or 'settled'; r.paid=amount; a.balance=a.balance+amount
  result={ok=true,balance=a.balance,paid=amount}
 elseif q.op=='deposit' or q.op=='withdraw' then
  if not integer(q.amount) or q.amount<1 then return fail('Positive whole diamond amount required') end
  if q.op=='withdraw' and a.balance<q.amount then return fail('Not enough credits') end
  if q.op=='withdraw' then a.balance=a.balance-q.amount end
  s.pending[q.id]={kind=q.op,account=q.account,amount=q.amount,beforeBank=s.bank}
  result={ok=true,pending=true,id=q.id}
 else return fail('Unknown operation') end
 s.transactions[q.id]={fingerprint=fingerprint,result=result}
 return result
end
function M.complete(s,id,moved)
 local p=s.pending[id]
 assert(p,'No pending transfer')
 assert(integer(moved) and moved<=p.amount,'Invalid transferred count')
 local a=s.accounts[p.account]
 if p.kind=='deposit' then s.bank=s.bank+moved; a.balance=a.balance+moved
 else s.bank=s.bank-moved; a.balance=a.balance+p.amount-moved end
 local result={ok=true,moved=moved,balance=a.balance,id=id}
 s.transactions[id].result=result; s.pending[id]=nil
 assert(M.available(s)>=0,'Unbacked ledger')
 return result
end
return M
]])

