writeFile('derby/server.lua', [[
local config=require('derby.config')
local store=require('derby.store')
local house=require('derby.house')
local service=require('derby.service')
local ledger=require('derby.ledger')
local ui=require('derby.ui')
local M={}
function M.run(c)
 config.network(c)
 local initial=house.new(require('derby.odds')); initial.paused=true
 local db=store.open('/house-bank/state',initial)
 local host=service.new(db,c,peripheral.wrap)
 local t=term.current(); local message='P: start after live acceptance. F: recognise funded bank.'
 local function draw()
  local s=host:state(); ui.clear(t,'HOUSE HOST | ID '..os.getComputerID())
  ui.line(t,3,' Bank: '..s.bank..' diamonds | Available: '..ledger.available(s))
  ui.line(t,5,' '..(s.paused and 'PAUSED' or 'RUNNING')..' | '..(s.race and s.race.id..' '..s.race.phase or 'Awaiting first race'))
  ui.line(t,7,' [P] Pause/start  [C] Cancel unstarted race')
  ui.line(t,9,' [F] Recognise added house diamonds')
  ui.line(t,11,' [R] Reconcile transfer  [U] Refund interrupted game')
  local y=13
  for id,p in pairs(s.pending) do ui.line(t,y,' PENDING '..id..' '..p.kind..' '..p.amount); y=y+1 end
  for id,r in pairs(s.rounds) do if r.status=='open' and r.game~='derby' then ui.line(t,y,' OPEN '..id..' '..r.game); y=y+1 end end
  local _,h=t.getSize(); ui.line(t,h-1,message,colors.yellow); ui.line(t,h,' [Q] Stop host (all clients go offline)')
 end
 local timer=os.startTimer(.1); draw()
 while true do
  local e,a,b,p=os.pullEvent()
  if e=='timer' and a==timer then
   host:tick(os.epoch('utc')%2147483646); timer=os.startTimer(.1); draw()
  elseif e=='rednet_message' and p=='pine-derby-house-v1' and type(b)=='table' and type(b.token)=='string' then
   local role=c.clients[tostring(a)]
   local result=role and host:request(b.request,role,a) or {ok=false,error='Computer not registered at house host'}
   rednet.send(a,{token=b.token,result=result},p)
  elseif e=='key' then
   local result
   if a==keys.q then return
   elseif a==keys.p then result=host:operator('pause')
   elseif a==keys.c then result=host:operator('cancel')
   elseif a==keys.f then result=host:operator('fund')
   elseif a==keys.r or a==keys.u then
    t.setCursorPos(1,15); t.clearLine(); write(a==keys.r and 'Transaction ID: ' or 'Round ID: '); local id=read()
    if a==keys.r then write('Verified diamonds actually moved: '); result=host:operator('reconcile',id,tonumber(read()))
    else result=host:operator('refund',id) end
   end
   if result then message=result.ok and 'Saved and verified' or result.error; draw() end
  end
 end
end
return M
]])

writeFile('derby/service.lua', [[
local store=require('derby.store')
local ledger=require('derby.ledger')
local house=require('derby.house')
local inventory=require('derby.inventory')
local M={}
function M.new(storage,config,wrap)
 local s=storage:get()
 -- Reconstruct exact floating-point state instead of trusting JSON-rounded positions.
 if s.race and s.race.sim then
  local sim=require('derby.sim')
  assert(s.race.sim.version==sim.version,'Saved race requires its original simulation version')
  local restored=sim.new(s.race.seed)
  for _=1,s.race.sim.tick do sim.step(restored) end
  s.race.sim=restored
 end
 local api={}
 local function commit(nextState)
  storage:save(nextState); s=nextState
 end
 local function denied(message) return {ok=false,error=message} end
 function api:state() return store.copy(s) end
 function api:request(q,role,owner)
  if type(q)~='table' or type(q.op)~='string' then return denied('Invalid request') end
  if q.op=='snapshot' then return house.snapshot(s,q.account) end
  if q.op=='lookup' or q.op=='status' or q.op=='roundStatus' then return ledger.apply(s,q) end
  if role=='display' then return denied('Display is read only') end
  if type(q.id)~='string' or not q.id:match('^'..tostring(owner)..':') then return denied('Wrong transaction owner') end
  if q.op=='create' or q.op=='deposit' or q.op=='withdraw' then
   if role~='cashier' then return denied('Cashier operation') end
  elseif q.op~='bet' and q.op~='reserve' and q.op~='increase' and q.op~='settle' and q.op~='refund' then return denied('Operation not available remotely') end
  local nextState=store.copy(s)
  local request=store.copy(q); request.owner=tostring(owner)
  -- A repeated transfer must return its receipt without touching inventories again.
  local existed=nextState.transactions[request.id]~=nil
  local result=request.op=='bet' and house.bet(nextState,request) or ledger.apply(nextState,request)
  if not result.ok then return result end
  commit(nextState)
  if (q.op=='deposit' or q.op=='withdraw') and not existed then
   -- Intent is durable before either physical side effect.
   local ok,moved=pcall(function()
    local bank=assert(wrap(config.bank),'Bank unavailable')
    assert(inventory.count(bank)==s.bank,'Bank count differs from ledger; reconcile before transfer')
    if q.op=='deposit' then return inventory.move(assert(wrap(config.intake)),config.bank,q.amount) end
    return inventory.move(bank,config.payout,q.amount)
   end)
   if not ok then return denied('Transfer uncertain; operator reconciliation required: '..tostring(moved)) end
   nextState=store.copy(s)
   local receipt=ledger.complete(nextState,q.id,moved)
   commit(nextState)
   return receipt
  end
  return result
 end
 function api:tick(seed)
  local n=store.copy(s); house.tick(n,seed)
  -- Save every second and every phase boundary. Replayed sub-second steps use the saved RNG.
  local boundary=not s.race or (n.race and n.race.phase~=s.race.phase)
  if boundary or (n.race and n.race.elapsed%10==0) then commit(n) else s=n end
 end
 function api:operator(op,id,amount)
  local n=store.copy(s)
  if op=='pause' then n.paused=not n.paused
  elseif op=='cancel' then local r=house.cancel(n); if not r.ok then return r end
  elseif op=='fund' then
   if next(n.pending) then return denied('Reconcile pending transfer first') end
   local count=inventory.count(assert(wrap(config.bank)))
   if count<n.bank then return denied('Bank shortage: restore missing diamonds before continuing') end
   local r=ledger.apply(n,{op='fund',id='fund:'..tostring(os.epoch('utc')),amount=count}); if not r.ok then return r end
  elseif op=='reconcile' then
   local p=n.pending[id]; if not p then return denied('No such pending transfer') end
   if type(amount)~='number' or amount%1~=0 or amount<0 or amount>p.amount then return denied('Invalid moved amount') end
   local expected=p.beforeBank+(p.kind=='deposit' and amount or -amount)
   if inventory.count(assert(wrap(config.bank)))~=expected then return denied('Count does not match bank; inspect intake/output and restore consistency') end
   ledger.complete(n,id,amount)
  elseif op=='refund' then
   local r=n.rounds[id]
   if not r or r.status~='open' or r.game=='derby' then return denied('No interrupted arcade round with this ID') end
   local result=ledger.apply(n,{op='refund',id='operator-refund:'..id,round=id,account=r.account,owner=r.owner})
   if not result.ok then return result end
  else return denied('Unknown operator action') end
  commit(n); return {ok=true}
 end
 return api
end
return M
]])

writeFile('derby/sim.lua', [[
-- Pure, versioned simulation. Distances and time do not depend on the renderer.
local M = { version = 1, dt = .1, distance = 450 }
M.horses = {
 {name="COPPER COMET", style="STEADY", color=2},
 {name="LEDGER LIZARD", style="CLOSER", color=256},
 {name="NEON PANIC", style="CHAOS", color=1024},
}
local function random(s)
 s.rng = (s.rng * 48271) % 2147483647
 return s.rng / 2147483647
end
function M.new(seed)
 local s={seed=seed, rng=math.floor(seed)%2147483646+1, tick=0, horses={}, order={}, version=M.version}
 for _=1,8 do random(s) end
 for i=1,3 do s.horses[i]={distance=0, ability=.88+random(s)*.24, surge=0} end
 return s
end
function M.step(s)
 if #s.order == 3 then return s end
 s.tick=s.tick+1
 local crossing={}
 for i,h in ipairs(s.horses) do
  if not h.finish then
   local p=h.distance/M.distance
   local r=random(s)
   local speed
   if i==1 then speed=.95+r*.12
   elseif i==2 then speed=.82+.36*p+(r-.5)*.2
   else speed=.99+(r-.5)*1.6; if r>.97 then speed=2.5 elseif r<.04 then speed=0 end end
   if s.tick%25==1 then h.surge=(random(s)-.5)*.25 end
   speed=math.max(.03,(speed+h.surge)*h.ability)
   local previous=h.distance
   h.distance=previous+speed
   if h.distance>=M.distance then
    h.finish=(s.tick-1+(M.distance-previous)/speed)*M.dt
    crossing[#crossing+1]={id=i,time=h.finish,tie=random(s)}
   end
  end
 end
 table.sort(crossing,function(a,b) if a.time==b.time then return a.tie<b.tie end return a.time<b.time end)
 for _,c in ipairs(crossing) do s.order[#s.order+1]=c.id end
 return s
end
function M.run(seed)
 local s=M.new(seed)
 while #s.order<3 do M.step(s) end
 return s
end
function M.positions(s)
 local out={}
 for i,h in ipairs(s.horses) do out[i]=math.min(1,h.distance/M.distance) end
 return out
end
return M
]])

writeFile('derby/station.lua', [[
local ui=require('derby.ui')
local sim=require('derby.sim')
local M={}
function M.run(client,t)
 local horse,stakeIndex,focus=1,1,1
 local stakes={5,10,20}; local status=''; local review
 local snapshot={}; local account,balance,card
 local timer=os.startTimer(0)
 local function refresh()
  card=ui.card(); account=card and card.account
  local r=client:read({op='snapshot',account=account})
  snapshot=r
  if account then local a=client:read({op='lookup',account=account}); balance=a.ok and a.balance or nil; if not a.ok then status=a.error end else balance=nil end
 end
 local function draw()
  if not ui.usable(t) then return end
  ui.clear(t,'DERBY BETTING')
  ui.line(t,2,account and (' Balance: '..tostring(balance or 'UNAVAILABLE')..' credits') or ' Insert a house account card',colors.yellow)
  if review then
   ui.line(t,4,' CONFIRM YOUR TICKET',colors.yellow)
   ui.line(t,6,' '..review.horse..' '..sim.horses[review.horse].name)
   ui.line(t,8,' Stake: '..review.stake..' credits')
   ui.line(t,10,' Total return if winner: '..review.returns)
   ui.line(t,11,' Includes your stake | 1 credit = 1 diamond')
   ui.button(t,13,'ENTER: PLACE BET',true,false)
   ui.line(t,17,' Backspace: back | Q: exit')
  else
   ui.line(t,3,snapshot.ok and (' '..tostring(snapshot.phase)..' | '..tostring(snapshot.seconds or 0)..'s'..(snapshot.paused and ' | PAUSED' or '')) or ' HOUSE OFFLINE - BETTING UNAVAILABLE',colors.yellow)
   for i,h in ipairs(sim.horses) do
    local returns=snapshot.payouts and snapshot.payouts[i][tostring(stakes[stakeIndex])]
    ui.button(t,4+(i-1)*3,i..' '..h.name..' | return '..tostring(returns or '--'),focus==i,horse==i)
   end
   ui.line(t,14,(focus==4 and '> ' or '  ')..'Stake: '..stakes[stakeIndex]..'  [Left/Right]',colors.white,focus==4 and colors.blue or colors.black)
   ui.button(t,15,snapshot.ticket and 'TICKET ACCEPTED' or 'REVIEW BET',focus==5,false)
   ui.line(t,18,' Tab/Arrows | Enter | R: retry | Q: exit')
  end
  local w,h=t.getSize(); ui.line(t,h,' '..status,colors.yellow)
 end
 local function activate()
  if not ui.usable(t) then return end
  if review then
   local now=ui.card()
   if not now or now.account~=review.account then status='Card changed. Bet not sent.'; review=nil; return end
   local r=client:mutate({op='bet',account=review.account,race=review.race,horse=review.horse,stake=review.stake})
   status=r.ok and 'Ticket accepted. Winnings reach your account.' or r.error; review=nil; refresh()
  elseif focus<=3 then horse=focus
  elseif focus==4 then stakeIndex=stakeIndex%3+1
  elseif snapshot.ok and snapshot.phase=='OPEN' and not snapshot.paused and account and balance and not snapshot.ticket then
   review={account=account,race=snapshot.id,horse=horse,stake=stakes[stakeIndex],returns=snapshot.payouts[horse][tostring(stakes[stakeIndex])]}
  else status='Bet unavailable: check card, host and race status.' end
 end
 draw()
 while true do
  local e,a,b,c=os.pullEvent()
  if e=='timer' and a==timer then refresh(); timer=os.startTimer(1)
  elseif e=='key' then
   if a==keys.q then return
   elseif a==keys.r then local r=client:retry(); status=r.ok and 'Request acknowledged' or r.error; refresh()
   elseif a==keys.backspace then review=nil
   elseif a==keys.enter then activate()
   elseif not review then
    if a==keys.tab or a==keys.down then focus=focus%5+1 elseif a==keys.up then focus=(focus-2)%5+1
    elseif a==keys.left then stakeIndex=(stakeIndex-2)%3+1 elseif a==keys.right then stakeIndex=stakeIndex%3+1 end
   end
  elseif e=='monitor_touch' or e=='mouse_click' then
   local y=c
   if review and y>=13 and y<=15 then activate()
   elseif not review then
    if y>=4 and y<=12 then focus=math.floor((y-4)/3)+1; activate()
    elseif y==14 then focus=4; activate()
    elseif y>=15 and y<=17 then focus=5; activate() end
   end
  end
  draw()
 end
end
return M
]])

writeFile('derby/store.lua', [[
-- Two generation slots: interrupted writes leave the previous committed state.
local M={}
local function checksum(s)
 local n=0
 for i=1,#s do n=(n*31+s:byte(i))%2147483647 end
 return n
end
function M.copy(t)
 if type(t)~='table' then return t end
 local out={}; for k,v in pairs(t) do out[M.copy(k)]=M.copy(v) end
 return out
end
function M.open(base, initial)
 local seq=0
 local state
 local seen=false
 for slot=0,1 do
  local path=base..'.'..slot
  if fs.exists(path) then
   seen=true
   local f=fs.open(path,'r'); local data=f and f.readAll(); if f then f.close() end
   local ok,v=pcall(textutils.unserializeJSON,data or '')
   if ok and type(v)=='table' and type(v.payload)=='string' and type(v.seq)=='number' and checksum(v.payload)==v.checksum then
    local good,p=pcall(textutils.unserializeJSON,v.payload)
    if good and type(p)=='table' and v.seq>seq then state=p; seq=v.seq end
   end
  end
 end
 assert(state or not seen,'Both saved state slots are invalid; restore backup. No new bank was created.')
 state=state or M.copy(initial)
 local api={}
 function api:get() return M.copy(state) end
 function api:save(value)
  local payload=textutils.serializeJSON(M.copy(value))
  local path=base..'.'..((seq+1)%2)
  fs.makeDir(fs.getDir(base))
  local f=assert(fs.open(path,'w'),'Cannot persist '..path)
  f.write(textutils.serializeJSON({seq=seq+1,payload=payload,checksum=checksum(payload)})); f.close()
  local verify=assert(fs.open(path,'r')); local disk=textutils.unserializeJSON(verify.readAll()); verify.close()
  assert(disk and disk.payload==payload and disk.checksum==checksum(payload),'Persistence readback failed')
  seq=seq+1; state=M.copy(value)
 end
 return api
end
return M
]])

writeFile('derby/ui.lua', [[
local M={}
function M.line(t,y,text,fg,bg)
 local w,h=t.getSize(); if y<1 or y>h then return end
 t.setCursorPos(1,y); t.setTextColor(fg or colors.white); t.setBackgroundColor(bg or colors.black)
 t.write((tostring(text)..string.rep(' ',w)):sub(1,w))
end
function M.clear(t,title)
 require('derby.palette').apply(t)
 t.setBackgroundColor(colors.black); t.setTextColor(colors.white); t.clear()
 M.line(t,1,' '..title,colors.white,colors.blue)
end
function M.button(t,y,label,focused,selected)
 local w=t.getSize(); local bg=focused and colors.white or colors.gray; local fg=focused and colors.black or colors.white
 local prefix=(focused and '> ' or '  ')..(selected and '[X] ' or '[ ] ')
 for row=y,y+2 do M.line(t,row,row==y+1 and prefix..label or '',fg,bg) end
 return {y=y,height=3}
end
function M.card()
 for _,name in ipairs(peripheral.getNames()) do
  if peripheral.getType(name)=='drive' then
   local path=disk.getMountPath(name)
   if path then
    local account
    if fs.exists(path..'/house-card.json') then
     local f=fs.open(path..'/house-card.json','r'); local ok,v=pcall(textutils.unserializeJSON,f.readAll()); f.close()
     if ok and type(v)=='table' then account=v.account end
    end
    return {path=path,drive=name,diskID=disk.getID(name),account=account}
   end
  end
 end
end
function M.target()
 local monitor=peripheral.find('monitor')
 if monitor then monitor.setTextScale(1); return monitor end
 return term.current()
end
function M.usable(t)
 if not t.isColor() then
  t.setBackgroundColor(colors.black); t.setTextColor(colors.white); t.clear(); t.setCursorPos(1,1)
  t.write('Use an advanced colour computer/monitor.'); return false
 end
 local w,h=t.getSize()
 if w>=39 and h>=19 then return true end
 M.clear(t,'HOUSE'); M.line(t,3,'Display needs at least 39 x 19.'); M.line(t,5,'Resize or use a larger monitor.'); return false
end
return M
]])

